package com.campuscourier.parcel.dto;

import com.campuscourier.parcel.model.ParcelType;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import java.math.BigDecimal;

/**
 * JSON body for POST /api/parcels.
 *
 * Only client-supplied data lives here: id, trackingId, status and fees
 * are all generated by the backend, so clients cannot (and need not)
 * provide them. Violations return HTTP 400 automatically (see
 * GlobalExceptionHandler) because the controller marks this @Valid.
 */
public class CreateParcelRequest {

    @NotNull(message = "parcelType is required (DOCUMENT, FRAGILE or BULK)")
    private ParcelType parcelType;

    @NotBlank(message = "senderName must not be blank")
    private String senderName;

    @NotBlank(message = "recipientName must not be blank")
    private String recipientName;

    @NotBlank(message = "pickupLocation must not be blank")
    private String pickupLocation;

    @NotBlank(message = "destination must not be blank")
    private String destination;

    @NotNull(message = "weight is required")
    @Positive(message = "weight must be greater than zero")
    private BigDecimal weight;

    public ParcelType getParcelType() {
        return parcelType;
    }

    public void setParcelType(ParcelType parcelType) {
        this.parcelType = parcelType;
    }

    public String getSenderName() {
        return senderName;
    }

    public void setSenderName(String senderName) {
        this.senderName = senderName;
    }

    public String getRecipientName() {
        return recipientName;
    }

    public void setRecipientName(String recipientName) {
        this.recipientName = recipientName;
    }

    public String getPickupLocation() {
        return pickupLocation;
    }

    public void setPickupLocation(String pickupLocation) {
        this.pickupLocation = pickupLocation;
    }

    public String getDestination() {
        return destination;
    }

    public void setDestination(String destination) {
        this.destination = destination;
    }

    public BigDecimal getWeight() {
        return weight;
    }

    public void setWeight(BigDecimal weight) {
        this.weight = weight;
    }
}
